select lang.id, 'Test type TOEIC-like — Niveau 3', '{"duration_minutes": 45, "part_a": [{"question": "Complète : She ___ to the gym every morning before work.", "options": ["go", "goes", "going", "gone"], "correct_index": 1}, {"question": "Complète : We ___ in this city since 2015.", "options": ["live", "lived", "have lived", "are living"], "correct_index": 2}, {"question": "Complète : If it ___ tomorrow, we''ll cancel the picnic.", "options": ["rain", "rains", "rained", "will rain"], "correct_index": 1}, {"question": "Complète : The new policy ___ next month.", "options": ["will introduce", "will be introduced", "introduces", "is introduce"], "correct_index": 1}, {"question": "Complète : I don''t know ___ she''s coming to the party.", "options": ["if", "that", "when", "so"], "correct_index": 0}, {"question": "Complète : ___ you seen the new office yet?", "options": ["Do", "Did", "Have", "Are"], "correct_index": 2}, {"question": "Complète : This is the book ___ changed my perspective.", "options": ["who", "which", "whose", "where"], "correct_index": 1}, {"question": "Complète : She''s interested ___ learning Korean.", "options": ["to", "in", "on", "for"], "correct_index": 1}, {"question": "Complète : He admitted ___ the last deadline.", "options": ["miss", "to miss", "missing", "missed"], "correct_index": 2}, {"question": "Complète : Not only ___ late, but he also forgot his badge.", "options": ["he was", "was he", "did he arrive", "he arrived"], "correct_index": 1}, {"question": "Complète : This form ___ by Friday at the latest.", "options": ["must submit", "must be submitted", "must submitted", "must being submitted"], "correct_index": 1}, {"question": "Complète : If only I ___ about the meeting earlier!", "options": ["knew", "know", "had known", "will know"], "correct_index": 2}, {"question": "Complète : The woman ___ car is parked outside is my manager.", "options": ["who", "whom", "whose", "which"], "correct_index": 2}, {"question": "Complète : They ___ lunch when the fire alarm went off.", "options": ["had", "have had", "were having", "has"], "correct_index": 2}, {"question": "Complète : It''s essential that the report ___ accurate.", "options": ["is", "be", "was", "will be"], "correct_index": 1}, {"question": "Complète : Employees ___ wear identification badges at all times.", "options": ["must", "should to", "have", "can to"], "correct_index": 0}, {"question": "Complète : This laptop is ___ than the previous model.", "options": ["fast", "faster", "fastest", "more fast"], "correct_index": 1}, {"question": "Complète : ___ the delays, the project was finished on time.", "options": ["Although", "Because", "Despite", "So"], "correct_index": 2}, {"question": "Complète : She ___ have forgotten; she''s usually very reliable.", "options": ["mustn''t", "can''t", "shouldn''t", "won''t"], "correct_index": 1}, {"question": "Complète : What surprised us most ___ how quickly the team adapted.", "options": ["is", "are", "was being", "were"], "correct_index": 0}, {"question": "Complète : He''s not used to ___ in front of large audiences.", "options": ["speak", "speaking", "spoke", "to speak"], "correct_index": 1}, {"question": "Complète : The launch date has been ___ to next quarter.", "options": ["pushed back", "pushed forward", "pushed off", "pushed away"], "correct_index": 0}, {"question": "Complète : Neither the manager nor the team members ___ aware of the change.", "options": ["was", "is", "were", "has been"], "correct_index": 2}, {"question": "Complète : I''d rather we ___ this decision until tomorrow.", "options": ["postpone", "postponed", "will postpone", "postponing"], "correct_index": 0}, {"question": "Complète : Customer satisfaction ___ steadily over the past year.", "options": ["improved", "improves", "has improved", "improving"], "correct_index": 2}, {"question": "Complète : It''s her attention to detail ___ makes her so effective.", "options": ["that", "who", "which is", "what"], "correct_index": 0}, {"question": "Complète : He''s the type of colleague who always ___ a solution.", "options": ["find", "finds", "finding", "found"], "correct_index": 1}, {"question": "Complète : ___ being new to the role, she handled the crisis calmly.", "options": ["Despite", "Although", "In spite", "Because"], "correct_index": 0}, {"question": "Complète : I can''t find the invoice. I ___ deleted it by mistake.", "options": ["should have", "must have", "would have", "can have"], "correct_index": 1}, {"question": "Complète : The merger talks fell ___ after months of negotiation.", "options": ["through", "out", "up", "down"], "correct_index": 0}], "part_b": [{"title": "Annonce (voyage)", "passage": "Attention passengers: Flight 452 to Berlin has been delayed by approximately two hours due to technical issues. We apologize for the inconvenience. Passengers are invited to wait in the lounge area near Gate 12, where refreshments will be provided. Updates will be announced every thirty minutes.", "questions": [{"question": "What is the destination of the flight?", "options": ["Paris", "Berlin", "Rome", "Madrid"], "correct_index": 1}, {"question": "Why is the flight delayed?", "options": ["Weather", "Technical issues", "Staff shortage", "Not specified"], "correct_index": 1}, {"question": "How long is the delay?", "options": ["30 minutes", "One hour", "About two hours", "All day"], "correct_index": 2}, {"question": "Where should passengers wait?", "options": ["At the gate only", "The lounge area near Gate 12", "Outside the airport", "In the parking lot"], "correct_index": 1}, {"question": "What will be provided to passengers?", "options": ["Free tickets", "Refreshments", "Hotel rooms", "Nothing"], "correct_index": 1}, {"question": "How often will updates be given?", "options": ["Every hour", "Every thirty minutes", "Only at the end", "Continuously"], "correct_index": 1}]}, {"title": "Avis client (restaurant)", "passage": "I visited this restaurant last weekend for a birthday dinner. The staff were attentive and the food arrived quickly. The pasta dish was excellent, though the dessert was a bit disappointing. Prices were reasonable for the quality. I would come back, but perhaps skip the dessert next time.", "questions": [{"question": "What was the occasion?", "options": ["An anniversary", "A birthday dinner", "A business meeting", "A casual lunch"], "correct_index": 1}, {"question": "How was the service?", "options": ["Slow and rude", "Attentive and quick", "Average", "Not mentioned"], "correct_index": 1}, {"question": "What did the reviewer think of the pasta?", "options": ["Disappointing", "Excellent", "Average", "Too salty"], "correct_index": 1}, {"question": "What was the main disappointment?", "options": ["The main course", "The dessert", "The service", "The price"], "correct_index": 1}, {"question": "How were the prices described?", "options": ["Too expensive", "Reasonable", "Very cheap", "Not mentioned"], "correct_index": 1}, {"question": "Will the reviewer return?", "options": ["No, never", "Yes, but skip dessert", "Yes, for the dessert only", "Undecided"], "correct_index": 1}]}, {"title": "Article court (environnement)", "passage": "More cities are introducing bike-sharing programs to reduce traffic congestion and pollution. Early results show a modest drop in car usage during peak hours. However, some critics point out that bike lanes remain insufficient in many areas, making cycling less safe than it should be.", "questions": [{"question": "What are cities introducing?", "options": ["Car-sharing programs", "Bike-sharing programs", "New bus routes", "Toll roads"], "correct_index": 1}, {"question": "What is the goal of these programs?", "options": ["Increase tourism", "Reduce traffic and pollution", "Raise city revenue", "Promote local business"], "correct_index": 1}, {"question": "What do early results show?", "options": ["No change at all", "A modest drop in car usage", "A big increase in accidents", "Complete elimination of traffic"], "correct_index": 1}, {"question": "When is the drop in car usage observed?", "options": ["All day", "During peak hours", "Only on weekends", "At night"], "correct_index": 1}, {"question": "What do critics point out?", "options": ["Bikes are too expensive", "Bike lanes are insufficient", "Programs are unpopular", "No critics are mentioned"], "correct_index": 1}, {"question": "What is the overall tone of the article?", "options": ["Purely positive", "Balanced, noting both benefits and issues", "Purely negative", "Sarcastic"], "correct_index": 1}]}, {"title": "Email professionnel (candidature)", "passage": "Dear Hiring Manager, I am writing to apply for the Marketing Coordinator position advertised on your website. I have three years of experience in digital marketing and a strong background in content strategy. Please find my resume attached. I would welcome the opportunity to discuss my application further. Sincerely, Priya Nair.", "questions": [{"question": "What position is Priya applying for?", "options": ["Sales Manager", "Marketing Coordinator", "Content Writer", "HR Assistant"], "correct_index": 1}, {"question": "How much experience does she have?", "options": ["One year", "Three years", "Five years", "Not mentioned"], "correct_index": 1}, {"question": "What is her background in?", "options": ["Finance", "Content strategy", "Human resources", "Engineering"], "correct_index": 1}, {"question": "What is attached to the email?", "options": ["A cover letter", "Her resume", "A portfolio", "References"], "correct_index": 1}, {"question": "What does she request at the end?", "options": ["An immediate answer", "A chance to discuss her application", "A higher salary", "A remote position"], "correct_index": 1}, {"question": "Where did she see the job posting?", "options": ["A newspaper", "The company''s website", "A referral", "Not mentioned"], "correct_index": 1}]}, {"title": "Instructions (réservation en ligne)", "passage": "How to book a table: 1. Go to our website and click ''Reservations.'' 2. Choose your preferred date and time. 3. Enter the number of guests. 4. Provide your name and phone number. 5. Click ''Confirm'' to receive a confirmation email within a few minutes.", "questions": [{"question": "What is the first step?", "options": ["Enter guest number", "Click Reservations", "Choose date", "Provide phone number"], "correct_index": 1}, {"question": "What information is needed in step 3?", "options": ["Payment details", "Number of guests", "Table preference", "Dietary restrictions"], "correct_index": 1}, {"question": "What personal details are required?", "options": ["Only name", "Name and phone number", "Email and address", "Nothing personal"], "correct_index": 1}, {"question": "What happens after clicking Confirm?", "options": ["Nothing happens", "A confirmation email is sent", "You must call the restaurant", "Payment is required immediately"], "correct_index": 1}, {"question": "How quickly does the confirmation arrive?", "options": ["Instantly, no wait", "Within a few minutes", "Within 24 hours", "Not specified"], "correct_index": 1}, {"question": "How many steps are in the process?", "options": ["Three", "Four", "Five", "Six"], "correct_index": 2}]}]}'::jsonb
